const ADMIN_ID='9b19dda2-cdda-435b-bb14-b731eb79352c';
const $=id=>document.getElementById(id);
const money=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const date=new Intl.DateTimeFormat('pt-BR',{dateStyle:'medium',timeStyle:'short'});
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function message(text,error=false){const node=$('admin-message');node.textContent=text;node.classList.toggle('error',error);}
async function api(path,options={}){const response=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...options.headers}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(new Error(data.error||'Não foi possível carregar o painel.'),{status:response.status});return data;}
function showLogin(){ $('admin-dashboard').hidden=true;$('admin-login').hidden=false; }
async function showDashboard(){ $('admin-login').hidden=true;$('admin-dashboard').hidden=false;await refresh(); }
function rows(id,items,columns){const node=$(id);node.innerHTML=items.length?items.map(item=>`<tr>${columns.map(column=>`<td>${column(item)}</td>`).join('')}</tr>`).join(''):`<tr><td class="admin-empty" colspan="${columns.length}">Nenhum cadastro ainda.</td></tr>`;}
async function refresh(){message('Atualizando informações…');$('admin-refresh').disabled=true;try{const data=await api('admin/dashboard');$('total-sellers').textContent=new Intl.NumberFormat('pt-BR').format(data.totals.sellers);$('total-listings').textContent=new Intl.NumberFormat('pt-BR').format(data.totals.listings);$('total-sessions').textContent=new Intl.NumberFormat('pt-BR').format(data.totals.activeSessions);$('seller-count').textContent=`${data.sellers.length} exibidos`;$('listing-count').textContent=`${data.listings.length} exibidos`;rows('seller-rows',data.sellers,[s=>escape(s.displayName),s=>`<a href="mailto:${escape(s.email)}">${escape(s.email)}</a>`,s=>escape(s.listingCount),s=>date.format(s.createdAt)]);rows('listing-rows',data.listings,[v=>`${escape(v.make)} ${escape(v.model)} · ${escape(v.year)}`,v=>escape(v.sellerName),v=>escape(v.location),v=>money.format(v.price/100),v=>date.format(v.createdAt)]);message(`Dados atualizados às ${date.format(Date.now())}.`);}catch(error){if(error.status===401){showLogin();return;}message(error.message,true);}finally{$('admin-refresh').disabled=false;}}
$('admin-login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;const form=new FormData(event.currentTarget);try{const result=await api('login',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password')})});if(result.seller?.id!==ADMIN_ID)throw new Error('Esta conta não tem acesso à administração.');await showDashboard();}catch(error){const text=$('admin-login').querySelector('p');text.textContent=error.message;text.classList.add('admin-login-error');}finally{button.disabled=false;}});
$('admin-refresh').addEventListener('click',refresh);
$('admin-logout').addEventListener('click',async()=>{try{await api('logout',{method:'POST'});}finally{showLogin();}});
try{const result=await api('session');if(result.seller?.id===ADMIN_ID)await showDashboard();else showLogin();}catch{showLogin();}
